const svgPaths={poll:'<path d="M5 20V10M12 20V4M19 20v-7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',check:'<path d="m5 12 4 4L19 6"/>',tasks:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="m7 9 1.5 1.5L11 8m2 2h4M7 15h3m3 0h4"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',team:'<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="3"/><path d="M1 21v-3a6 6 0 0 1 12 0v3m1-7a5 5 0 0 1 8 4v3"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Zm0 2h18"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m18 7h-6v4h6"/>',chart:'<path d="M3 3v18h18M7 16v-5m5 5V7m5 9V4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',left:'<path d="m15 5-7 7 7 7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4 2 2-2a4 4 0 0 0-6-6L6 5" transform="translate(3 2) scale(.85)"/>',external:'<path d="M14 3h7v7m-1-6L10 14m-1-9H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7a3 3 0 0 0-5-5L3 15v6Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 3.1 5.2 2 2 0 0 1 5.1 3h3l2 5-3 2a16 16 0 0 0 7 7l2-3 5 2Z"/>',qr:'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h2v2h-2zm4 0h2v6h-6v-2m-3-7h2m4 0h3M3 12h6m3-9v6m0 7v5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',logout:'<path d="M9 3H3v18h6m0-9h12m-5-5 5 5-5 5"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 4v3"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 13h8m-8 4h8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',printer:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v8H6z"/>'};
svgPaths.chat='<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-3 2 1.5-6A8.5 8.5 0 1 1 21 11.5Z"/><path d="M6 10h10m-10 4h6"/>';
svgPaths.list='<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>';
svgPaths.bell='<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9M10.3 21a1.94 1.94 0 0 0 3.4 0"/>';
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${svgPaths[name]||svgPaths.grid}</svg>`;
const brand=(href="/")=>`<a class="brand" href="${esc(href)}" aria-label="EventGo — главная"><img src="/assets/mark.svg" alt=""><span>Event<em>Go</em></span></a>`;
const money=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(x??0)+' ₽';
const dateLong=x=>new Date(x).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
const dateShort=x=>new Date(x+'T12:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}).replace('.','');
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Yakutsk',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const initials=name=>name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=(name,i=0)=>`<span class="avatar ${['','orange','lime','blue'][i%4]}" title="${esc(name)}">${esc(initials(name))}</span>`;
const labels={todo:'Ожидание',progress:'В работе',done:'Готово',planning:'В подготовке',active:'Идёт сейчас',finished:'Завершено',registered:'Зарегистрирован',confirmed:'Подтверждён',attended:'Пришёл',cancelled:'Отменён',pending:'Обсуждение'};
const badge=(status,label)=>`<span class="badge ${esc(status)}">${esc(label||labels[status]||status)}</span>`;
const priority=x=>`<span class="priority ${x}">${x==='high'?'↑ Высокий':x==='low'?'↓ Низкий':'— Обычный'}</span>`;
const button=(text,action,ic='plus',cls='',data='')=>`<button class="button ${cls}" data-action="${action}" ${data}>${ic?icon(ic):''}${text}</button>`;
const empty=(title,description,action='')=>`<div class="empty">${icon('folder')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;
const s={user:null,events:[],eventId:Number(localStorage.getItem('eventgo-event'))||1,data:null,view:location.hash.slice(1)||'overview',search:'',filter:'all',board:false,month:today().slice(0,7),menu:false};
const nav=[['overview','grid','Обзор'],['events','calendar','Мероприятия'],['tasks','tasks','Задачи'],['program','list','Программа'],['guests','users','Участники'],['team','team','Команда'],['chat','chat','Чат команды'],['assistant','spark','ИИ-ассистент'],['files','folder','Файлы'],['budget','wallet','Бюджет'],['calendar','calendar','Календарь'],['analytics','chart','Аналитика'],['survey','poll','Опрос гостей']];
let modalSubmit=null,cleanupModal=null,toastTimer,loading=false;
const isOrg=()=>s.user?.role==='organizer';
const allowedNav=()=>nav.filter(([key])=>isOrg()||!['budget','analytics','survey'].includes(key));
const MAX_FILE_BYTES=4*1024**3;
const teamChat=new TeamChat({api,esc,avatar,icon,formatTime:activityTime});
const aiAssistant=new AIAssistant({api,esc,icon,formatTime:activityTime,openModal,toast});
async function api(path,method='GET',data){const response=await fetch('/api'+path,{method,headers:{'X-EventGo':'1',...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok){if(response.status===401&&s.user){s.user=null;renderLogin();}throw Object.assign(new Error(result.error||'Не удалось выполнить запрос.'),{status:response.status});}return result;}
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',4500);}
function openModal(title,content,{submit='',onSubmit=null,wide=false}={}){closeModal();modalSubmit=onSubmit;const m=$('#modal');m.style.width=wide?'min(760px,calc(100vw - 30px))':'';m.innerHTML=`<${onSubmit?'form id="modal-form"':'div'}><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-button" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${content}<p class="form-error" role="alert"></p></div>${onSubmit?`<div class="modal-footer"><button type="button" class="button secondary" data-action="close">Отмена</button><button class="button" type="submit">${esc(submit||'Сохранить')}</button></div>`:''}</${onSubmit?'form':'div'}>`;m.showModal();}
function closeModal(){if(cleanupModal){cleanupModal();cleanupModal=null;}$('#modal').close();modalSubmit=null;}
$('#modal').addEventListener('cancel',()=>{if(cleanupModal){cleanupModal();cleanupModal=null;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function field(label,name,value='',type='text',opts={}){const control=type==='textarea'?`<textarea name="${name}" ${opts.required===false?'':'required'} maxlength="${opts.max||4000}" placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:type==='select'?`<select name="${name}" ${opts.required===false?'':'required'}>${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input type="${type}" name="${name}" value="${esc(value)}" ${opts.required===false?'':'required'} ${type==='number'?`min="${opts.min??0}" max="10000000000" step="${opts.step||'1'}"`:`maxlength="${opts.max||500}"`} placeholder="${esc(opts.placeholder||'')}" ${type==='password'?'autocomplete="current-password"':''}>`;return `<label class="field ${opts.full?'full':''}"><span>${esc(label)}${opts.required===false?'':' <span aria-hidden="true">*</span>'}</span>${control}${opts.hint?`<small>${esc(opts.hint)}</small>`:''}</label>`;}
function formObject(form){return Object.fromEntries(new FormData(form));}
async function reload(render=true){s.notifications=await api('/notifications').catch(()=>s.notifications);s.events=await api('/events');if(!s.events.some(e=>e.id===s.eventId))s.eventId=s.events.find(e=>e.title==='IT-Форум 2026')?.id||s.events[0]?.id;if(s.eventId){localStorage.setItem('eventgo-event',s.eventId);s.data=await api('/events/'+s.eventId);}else s.data=null;if(render)renderShell();}
async function saved(path,method,data,message='Изменения сохранены'){await api(path,method,data);closeModal();await reload();toast(message);}
function eventSelect(){return s.events.length?`<select class="event-switch" aria-label="Выбрать мероприятие" data-change="event">${s.events.map(e=>`<option value="${e.id}" ${e.id===s.eventId?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`:'';}
function renderShell(){const current=allowedNav().find(n=>n[0]===s.view)||nav[0];$('#app').innerHTML=`<div class="mobile-overlay ${s.menu?'open':''}" data-action="menu"></div><aside class="sidebar ${s.menu?'open':''}">${brand()}<p class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</p><nav class="nav-list" aria-label="Основная навигация">${allowedNav().map(([key,ic,label])=>`<button class="nav-item ${key===s.view?'active':''}" data-action="nav" data-view="${key}" ${key===s.view?'aria-current="page"':''}>${icon(ic)}${label}${key==='tasks'&&s.data?.event.tasks.overdue?`<span class="count">${s.data.event.tasks.overdue}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace"><div class="workspace-icon">НТ</div><div><strong>Команда «Не по ТЗ»</strong><span>Пространство EventGo</span></div></div><div class="local-label"><i class="dot"></i>Данные сохранены на компьютере</div></div></aside><div class="app-shell"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><p class="breadcrumb">Рабочее пространство <span style="margin:0 10px">/</span> <strong>${current[2]}</strong></p><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Yakutsk'})}</span>${eventSelect()}<button class="icon-button bell" data-action="notifications" aria-label="Уведомления${s.notifications?.unread?`: ${s.notifications.unread} новых`:''}">${icon('bell')}${s.notifications?.unread?`<span class="bell-count">${s.notifications.unread>99?'99+':s.notifications.unread}</span>`:''}</button><button class="profile" data-action="profile" aria-label="Аккаунт и настройки">${avatar(s.user.name)}<span><strong>${esc(s.user.name.split(' ')[0])}</strong><small>${isOrg()?'Организатор':'Участник команды'}</small></span>${icon('down')}</button></div></header><main class="main" id="main"></main></div>`;renderMain();}
function renderMain(){teamChat.stop();aiAssistant.stop();if(!isOrg()&&['budget','analytics','survey'].includes(s.view)){$('#main').innerHTML=pageHeading('Доступ ограничен','Этот раздел доступен только организатору.');return;}const active=document.activeElement;const searchFocused=active?.matches('[data-search]'),position=active?.selectionStart;$('#main').innerHTML=(!s.data&&s.view!=='events')?`<div class="page-heading"><h1>Начнём с события</h1></div><div class="panel">${empty('Здесь будет ваше мероприятие','Создайте событие, добавьте команду и начните подготовку.',isOrg()?button('Создать событие','new-event'): '')}</div>`:({overview:overview,events:eventsView,tasks:tasksView,program:programView,guests:guestsView,team:teamView,chat:()=>pageHeading('Чат команды','Обсуждайте подготовку мероприятия в одном месте.')+teamChat.view(s.data.event),assistant:()=>pageHeading('ИИ-ассистент','Вопросы, идеи и помощь с подготовкой события.')+aiAssistant.view(s.data.event,s.user),files:filesView,budget:budgetView,calendar:calendarView,analytics:analyticsView,survey:surveyView}[s.view]||overview)();if(s.view==='survey'&&s.data)loadSurvey();if(s.view==='chat'&&s.data)teamChat.mount(s.eventId,s.user);if(s.view==='assistant'&&s.data)aiAssistant.mount(s.eventId,s.user);if(searchFocused){const i=$('[data-search]');if(i){i.focus();i.setSelectionRange(position,position);}}}
function pageHeading(title,description,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${s.view==='events'?'Ваше рабочее пространство':esc(s.data?.event.title||'EventGo')}</p><h1>${esc(title)}</h1>${description?`<p class="description">${esc(description)}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,note,ic,color=''){return `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ic)}</span></div><div class="metric-value">${value}</div><p class="metric-note">${note}</p></div>`;}
function taskRow(t){const overdue=t.status!=='done'&&t.due_date<today();return `<div class="task-row"><button class="task-check ${t.status==='done'?'done':''}" data-action="toggle-task" data-id="${t.id}" aria-label="${t.status==='done'?'Вернуть в работу':'Отметить выполненной'}: ${esc(t.title)}">${t.status==='done'?icon('check'):''}</button><div class="task-copy"><button class="task-name" data-action="task" data-id="${t.id}">${esc(t.title)}</button><p class="task-sub">${esc(t.assignee_name||'Без ответственного')}</p></div>${badge(overdue?'overdue':t.status,overdue?'Просрочено':undefined)}<span class="task-date ${overdue?'overdue':''}">${dateShort(t.due_date)}</span>${avatar(t.assignee_name||'?',t.assignee_id||0)}</div>`;}
function readiness(){const e=s.data.event;return `<div class="panel"><div class="panel-head"><h2>Готовность события</h2>${icon('spark')}</div><div class="readiness"><div class="ring"><svg viewBox="0 0 120 120"><circle class="track" cx="60" cy="60" r="49"/><circle class="fill" cx="60" cy="60" r="49" stroke-dasharray="${e.readiness*3.0788} 307.88"/></svg><div class="ring-number">${e.readiness}%<small>готово к старту</small></div></div><div class="readiness-copy"><strong>${e.tasks.done} из ${e.tasks.total} задач</strong><p>${e.tasks.progress} в работе<br>${e.tasks.overdue?`<span class="negative">${e.tasks.overdue} просрочено</span>`:'Все сроки под контролем'}</p></div></div><div class="deadline-strip">${icon('clock')}${daysLeft(e.starts_at)}</div></div>`;}
function plural(n,one,few,many){const word=n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?few:many;return `${n} ${word}`;}
function timeLabel(x){return x?.includes('T')?x.slice(11,16):'';}
function programRange(item){const start=timeLabel(item.starts_at),end=timeLabel(item.ends_at);return end?`${start}–${end}`:start;}
function programDay(item){return item.starts_at?dateShort(item.starts_at.slice(0,10)):'';}
function programList(items,{editable=false,compact=false}={}){if(!items?.length)return '';return `<ol class="program-timeline ${compact?'compact':''}">${items.map(item=>`<li class="program-item"><div class="program-time"><strong>${esc(programRange(item))}</strong><span>${esc(programDay(item))}</span></div><div class="program-copy"><h3>${esc(item.title)}</h3>${item.speaker||item.hall?`<p class="program-meta">${item.speaker?esc(item.speaker):''}${item.speaker&&item.hall?' · ':''}${item.hall?esc(item.hall):''}</p>`:''}${!compact&&item.description?`<p class="small muted">${esc(item.description)}</p>`:''}</div>${editable&&isOrg()?`<div class="row-actions"><button class="icon-button" data-action="edit-program" data-id="${item.id}" aria-label="Изменить ${esc(item.title)}">${icon('edit')}</button></div>`:''}</li>`).join('')}</ol>`;}
function daysLeft(date){const n=Math.ceil((Date.parse(date.slice(0,10)+'T00:00:00+09:00')-Date.parse(today()+'T00:00:00+09:00'))/86400000);return n>0?`До мероприятия: ${n} ${n%10===1&&n%100!==11?'день':n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?'дня':'дней'}`:n===0?'Мероприятие начинается сегодня':'Дата мероприятия уже наступила';}
function overview(){
 const {event:e,tasks,team,activities,program=[]}=s.data;
 const upcoming=tasks.filter(t=>t.status!=='done').slice(0,4);
 const programPreview=program.slice(0,4);
 const financial=isOrg()?`<section class="panel"><div class="panel-head"><h2>Бюджет под контролем</h2><button class="text-button" data-action="nav" data-view="budget">Подробнее ${icon('arrow')}</button></div>${e.expense.actual>e.budget?`<div class="alert">Бюджет превышен на ${money(e.expense.actual-e.budget)}.</div>`:e.expense.planned>e.budget?`<div class="alert">Плановые расходы превышают бюджет на ${money(e.expense.planned-e.budget)}.</div>`:''}<div class="budget-preview"><div class="budget-amount"><strong>${money(e.budget-e.expense.actual)}</strong><span>остаток бюджета</span></div>${[['План',e.expense.planned,''],['Факт',e.expense.actual,'actual']].map(([label,value,cls])=>`<div class="budget-bars ${cls}"><span>${label}</span><div class="progress-track"><i style="width:${Math.min(100,value/Math.max(e.budget,e.expense.planned,1)*100)}%"></i></div><b>${money(value)}</b></div>`).join('')}</div></section>`:'';
 return `<div class="page-heading"><div><p class="eyebrow">Всё важное — перед глазами</p><h1>${esc(e.title)}</h1><div class="event-meta"><span>${icon('calendar')}${dateLong(e.starts_at)} · ${esc(e.starts_at.slice(11))}</span><span>${icon('pin')}${esc(e.location)}</span>${badge(e.status)}</div></div><div class="heading-actions">${isOrg()?button('Добавить задачу','new-task'):'<span class="badge">Режим команды</span>'}${isOrg()?`<button class="icon-button" data-action="edit-event" aria-label="Настроить мероприятие">${icon('edit')}</button>`:''}</div></div>
 <div class="metric-grid">${metric('Задачи выполнены',`${e.tasks.done} <span class="muted" style="font-size:16px">/ ${e.tasks.total}</span>`,`${e.readiness}% плана подготовки`,'tasks')}${metric('В работе',e.tasks.progress,e.tasks.overdue?`<span class="warn">${e.tasks.overdue} просрочено</span>`:'Сроки под контролем','clock','orange')}${metric('Регистрации',e.guests.registered,`из ${e.capacity} доступных мест`,'users','green')}${isOrg()?metric('Бюджет события',money(e.budget),`Потрачено <b>${money(e.expense.actual)}</b>`,'wallet','blue'):metric('Команда события',team.length,'Сотрудники и подрядчики','team','blue')}</div>
 <div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Ближайшие задачи</h2><p class="sub">Небольшие шаги к большому событию</p></div><button class="text-button" data-action="nav" data-view="tasks">Все задачи ${icon('arrow')}</button></div>${upcoming.length?upcoming.map(taskRow).join(''):empty('Задачи выполнены','Можно добавить новые задачи для следующего этапа.')}<div class="panel-foot"><span class="small muted">${tasks.filter(t=>t.status!=='done').length} задач осталось</span>${isOrg()?`<button class="text-button" data-action="new-task">${icon('plus')} Добавить задачу</button>`:''}</div></section><section class="panel"><div class="panel-head"><div><h2>Программа</h2><p class="sub">${program.length?plural(program.length,'пункт','пункта','пунктов'):'Расписание ещё не собрано'}</p></div><button class="text-button" data-action="nav" data-view="program">Открыть ${icon('arrow')}</button></div>${programPreview.length?programList(programPreview,{compact:true}):empty('Программа пуста','Добавьте секции, время и спикеров.')}</section>${financial}
 <section class="panel"><div class="panel-head"><h2>Команда события</h2><button class="text-button" data-action="nav" data-view="team">Открыть ${icon('arrow')}</button></div><div class="team-preview"><div class="avatar-stack">${team.slice(0,5).map((p,i)=>avatar(p.name,i)).join('')}</div><p>${team.filter(p=>p.kind==='team').length} в команде · ${plural(team.filter(p=>p.kind==='contractor').length,'подрядчик','подрядчика','подрядчиков')}</p></div></section></div>
 <div class="stack">${readiness()}<section class="registration-card"><h2>Ваши гости уже здесь</h2><p>Одна ссылка для регистрации. Все участники в одном списке.</p><div class="registration-numbers"><strong>${e.guests.registered}</strong><span>/ ${e.capacity} мест</span></div><div class="progress-track"><i style="width:${e.guests.registered/e.capacity*100}%"></i></div><button class="button light" data-action="registration">${icon('link')} Страница регистрации ${icon('arrow')}</button></section>
 <section class="panel"><div class="panel-head"><h2>Лента события</h2><span class="dot"></span></div>${activities.slice(0,3).map((a,i)=>`<div class="activity-row">${avatar(a.actor,i)}<div><p><strong>${esc(a.actor)}</strong> ${esc(a.text)}</p><small>${activityTime(a.created_at)}</small></div></div>`).join('')||'<p class="muted small" style="padding:20px">Действий пока нет.</p>'}</section></div></div>`;
}
function activityTime(x){return new Date(x.includes('T')?x:x.replace(' ','T')+'Z').toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Yakutsk'});}
function searchBox(placeholder){return `<label class="search">${icon('search')}<input data-search value="${esc(s.search)}" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></label>`;}
function matches(...texts){return !s.search||texts.join(' ').toLowerCase().includes(s.search.toLowerCase());}
function tabs(items){return `<div class="tabs">${items.map(([key,label])=>`<button class="tab ${s.filter===key?'active':''}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}</div>`;}
function eventsView(){const events=s.events.filter(e=>matches(e.title,e.location)&&(s.filter==='all'||e.status===s.filter));return pageHeading('Мои мероприятия','От первой идеи до последнего гостя — всё в одном месте.',isOrg()?button('Создать событие','new-event'):'')+`<div class="toolbar">${tabs([['all','Все события'],['planning','В подготовке'],['active','Сейчас'],['finished','Завершённые']])}${searchBox('Найти мероприятие')}</div>${events.length?`<div class="event-cards">${events.map((e,i)=>`<article class="event-card"><div class="event-art ${['','orange','lime'][i%3]}">${icon(e.type==='Хакатон'?'spark':e.type==='Встреча'?'team':'calendar')}${badge(e.status)}</div><div class="event-card-body"><h2>${esc(e.title)}</h2><p>${icon('calendar')}${dateLong(e.starts_at)} · ${esc(e.starts_at.slice(11))}</p><p>${icon('pin')}${esc(e.location)}</p><div class="section-gap"><div class="toolbar" style="margin-bottom:7px;font-size:10px;color:var(--muted)"><span>Готовность</span><strong>${e.readiness}%</strong></div><div class="progress-track"><i style="width:${e.readiness}%"></i></div></div><div class="event-card-bottom"><span>${e.tasks.total} задач · ${e.guests.registered} гостей</span><button class="text-button" data-action="open-event" data-id="${e.id}">Открыть ${icon('arrow')}</button></div></div></article>`).join('')}</div>`:`<div class="panel">${empty('События не найдены','Измените фильтры или создайте новое мероприятие.')}</div>`}`;}
function filteredTasks(){return s.data.tasks.filter(t=>matches(t.title,t.assignee_name,t.description)&&(s.filter==='all'||s.filter==='mine'&&t.assignee_user_id===s.user.id||s.filter==='overdue'&&t.status!=='done'&&t.due_date<today()||s.filter===t.status));}
function statusSelect(t){const enabled=isOrg()||t.assignee_user_id===s.user.id;return `<select class="status-select" data-change="task-status" data-id="${t.id}" aria-label="Статус задачи ${esc(t.title)}" ${enabled?'':'disabled'}>${['todo','progress','done'].map(x=>`<option value="${x}" ${t.status===x?'selected':''}>${labels[x]}</option>`).join('')}</select>`;}
function tasksView(){const tasks=filteredTasks();return pageHeading('Задачи',`План подготовки · ${s.data.tasks.length} задач`,`${button(s.board?'Список':'Доска','board',s.board?'tasks':'grid','secondary')}${isOrg()?button('Добавить задачу','new-task'):''}`)+`<div class="toolbar">${tabs([['all','Все'],['mine','Мои задачи'],['overdue','Просроченные'],['done','Готово']])}${searchBox('Найти задачу')}</div>${s.board?`<div class="kanban">${['todo','progress','done'].map(status=>`<section class="kanban-column"><h3>${labels[status]}<span class="muted">${tasks.filter(t=>t.status===status).length}</span></h3>${tasks.filter(t=>t.status===status).map(t=>`<article class="kanban-card">${priority(t.priority)}<button class="task-name" data-action="task" data-id="${t.id}">${esc(t.title)}</button><div class="kanban-card-foot"><span class="task-date ${t.status!=='done'&&t.due_date<today()?'overdue':''}">${dateShort(t.due_date)}</span>${avatar(t.assignee_name||'?',t.assignee_id||0)}</div><div style="margin-top:10px">${statusSelect(t)}</div></article>`).join('')||'<p class="muted small" style="padding:10px">Пока нет задач</p>'}</section>`).join('')}</div>`:`<section class="panel">${tasks.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Задача</th><th>Ответственный</th><th>Срок</th><th>Приоритет</th><th>Статус</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="task-name" data-action="task" data-id="${t.id}">${esc(t.title)}</button></td><td>${t.assignee_name?avatar(t.assignee_name,t.assignee_id)+esc(t.assignee_name.split(' ')[0]):'<span class="muted">Не назначен</span>'}</td><td class="${t.status!=='done'&&t.due_date<today()?'negative':''}">${dateShort(t.due_date)}</td><td>${priority(t.priority)}</td><td>${statusSelect(t)}</td></tr>`).join('')}</tbody></table></div>`:empty('Задачи не найдены','Измените фильтр или добавьте новую задачу.')}</section>`}`;}
async function notificationsModal(){const data=await api('/notifications/seen','POST');const items=data.items;const view={task:'tasks',guests:'guests',budget:'budget'};openModal('Уведомления',items.length?`<div class="notice-list">${items.map((n,i)=>`<button type="button" class="notice-item ${n.level}" data-action="open-notification" data-index="${i}"><span class="notice-dot"></span><span><strong>${esc(n.text)}</strong><small>${esc(n.event_title)}${n.kind==='task'&&n.date?` · срок ${dateShort(n.date)}`:''}${n.unread?' · новое':''}</small></span>${icon('chevron')}</button>`).join('')}</div>`:empty('Всё спокойно','Просроченных задач, новых регистраций и перерасхода бюджета нет.'));s.noticeItems=items.map(n=>({...n,view:view[n.kind]}));s.notifications={...data,unread:items.filter(x=>x.level==='danger').length};const bell=$('.bell-count');if(bell){if(s.notifications.unread)bell.textContent=s.notifications.unread;else bell.remove();}}
async function openNotification(index){const n=s.noticeItems?.[index];if(!n)return;closeModal();if(n.kind==='budget'&&!isOrg())return;s.eventId=n.event_id;s.view=n.view;s.filter='all';s.search='';location.hash=n.view;await reload();if(n.task_id)await taskDetail(n.task_id);}
function guestForm(){openModal('Добавить гостя',`<div class="form-grid">${field('Имя и фамилия','name','','text',{full:true,max:120})}${field('Электронная почта','email','','email',{max:200})}${field('Телефон','phone','','tel',{required:false,max:40})}${field('Организация','company','','text',{required:false,max:160})}${field('Статус','status','confirmed','select',{options:[['confirmed','Подтверждён'],['registered','Зарегистрирован']]})}</div><p class="small muted" style="margin-top:15px">Гость получит личный билет с QR-кодом — его можно показать или отправить ссылкой. Добавляйте только тех, кто согласился на участие.</p>`,{submit:'Добавить гостя',onSubmit:async form=>{const result=await api('/events/'+s.eventId+'/guests','POST',formObject(form));await reload();toast('Гость добавлен');await ticketModal(result.ticket);return false;}});}
function parseCsv(text){text=text.replace(/^\ufeff/,'');const first=text.split(/\r?\n/,1)[0]||'';const delimiter=[';','\t',','].reduce((best,d)=>first.split(d).length>first.split(best).length?d:best,';');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"')quoted=true;else if(c===delimiter){row.push(cell);cell='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}if(cell||row.length){row.push(cell);rows.push(row);}return rows;}
function guestRowsFromCsv(text){const rows=parseCsv(text);if(!rows.length)return [];const head=rows[0].map(x=>x.trim().toLowerCase());const find=re=>head.findIndex(h=>re.test(h));let columns={name:find(/имя|фио|name/),email:find(/почт|e-?mail/),phone:find(/тел|phone/),company:find(/орган|компан|company/)},start=1;if(columns.email<0){columns={name:0,email:1,phone:2,company:3};start=0;}return rows.slice(start).map((cells,i)=>({line:i+start+1,cells})).filter(r=>r.cells.some(x=>x.trim())).map(({line,cells})=>({line,name:(cells[columns.name]??'').trim(),email:(cells[columns.email]??'').trim(),phone:columns.phone>=0?(cells[columns.phone]??'').trim():'',company:columns.company>=0?(cells[columns.company]??'').trim():''}));}
async function readTextFile(file){const bytes=await file.arrayBuffer();try{return new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{return new TextDecoder('windows-1251').decode(bytes);}}
function importGuestsForm(){openModal('Импорт гостей из CSV',`<div class="form-grid"><label class="field full"><span>Файл CSV · до 2000 строк <span aria-hidden="true">*</span></span><input name="file" type="file" accept=".csv,.txt,text/csv" required></label>${field('Статус гостей','status','confirmed','select',{full:true,options:[['confirmed','Подтверждён'],['registered','Зарегистрирован']]})}</div><div class="notice" style="margin-top:15px"><p class="small"><strong>Формат:</strong> столбцы «Имя», «Почта», «Телефон», «Организация». Подойдёт файл, сохранённый из Excel как «CSV (разделители — точки с запятой)». Если заголовка нет, порядок столбцов такой же.</p></div><p class="small muted" style="margin-top:12px">Повторные почты, строки с ошибками и гости сверх лимита мест будут пропущены — сайт покажет, какие именно.</p>`,{submit:'Загрузить гостей',onSubmit:async form=>{const file=form.file.files[0];if(file.size>1048576)throw new Error('Файл больше 1 МБ. Разделите список на части.');const rows=guestRowsFromCsv(await readTextFile(file));if(!rows.length)throw new Error('В файле не найдено строк с гостями.');const result=await api('/events/'+s.eventId+'/guests/import','POST',{rows,status:form.status.value});await reload();openModal('Импорт завершён',`<p style="font-size:14px"><strong>Добавлено гостей: ${result.added}</strong>${result.skipped.length?` · пропущено: ${result.skipped.length}`:''}</p>${result.skipped.length?`<div class="table-wrap section-gap"><table class="data-table"><thead><tr><th>Строка</th><th>Причина</th></tr></thead><tbody>${result.skipped.slice(0,50).map(x=>`<tr><td>${x.line}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div>${result.skipped.length>50?`<p class="small muted" style="margin-top:10px">И ещё ${result.skipped.length-50} строк.</p>`:''}`:'<p class="small muted" style="margin-top:10px">Все строки загружены без ошибок.</p>'}`);return false;}});}
function programView(){const items=(s.data.program||[]).filter(p=>matches(p.title,p.speaker,p.hall,p.description));return pageHeading('Программа',`Расписание дня · ${(s.data.program||[]).length} пунктов`,isOrg()?button('Добавить пункт','new-program'):'')+`<div class="toolbar">${searchBox('Найти по названию, спикеру или залу')}</div><div class="panel pad">${items.length?programList(items,{editable:true}):empty('Программа ещё не составлена','Соберите секции, время, залы и спикеров — гости увидят расписание на странице регистрации и в билете.',isOrg()?button('Добавить пункт','new-program'):'')}</div>`;}
function programForm(id){const p=id?(s.data.program||[]).find(x=>x.id===Number(id)):{};const day=s.data.event.starts_at.slice(0,10);openModal(id?'Пункт программы':'Новый пункт программы',`<div class="form-grid">${field('Название','title',p.title,'text',{full:true,max:200,placeholder:'Например, Открытие форума'})}${field('Начало','starts_at',p.starts_at||`${day}T10:00`,'datetime-local')}${field('Окончание','ends_at',p.ends_at||`${day}T11:00`,'datetime-local',{required:false})}${field('Спикер','speaker',p.speaker,'text',{required:false,max:160})}${field('Зал / площадка','hall',p.hall,'text',{required:false,max:120,placeholder:'Главный зал'})}${field('Описание','description',p.description,'textarea',{full:true,required:false,max:2000})}${field('Порядок','sort_order',p.sort_order??0,'number',{min:0})}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-program" data-id="${id}">${icon('trash')} Удалить пункт</button>`:''}`,{submit:id?'Сохранить':'Добавить в программу',onSubmit:async form=>{const data=formObject(form);data.sort_order=Number(data.sort_order)||0;if(!data.ends_at)data.ends_at='';await saved(id?'/program/'+id:'/events/'+s.eventId+'/program',id?'PATCH':'POST',data,id?'Пункт обновлён':'Пункт добавлен в программу');}});}
function guestsView(){const e=s.data.event,guests=s.data.guests.filter(g=>matches(g.name,g.email,g.company)&&(s.filter==='all'||g.status===s.filter));return pageHeading('Участники',`${e.guests.registered} регистраций из ${e.capacity} мест`,`${isOrg()?button('Проверить билет','checkin','qr','secondary')+button('Импорт CSV','import-guests','upload','secondary')+button('Добавить гостя','new-guest','plus','secondary'):''}${button('Регистрация','registration','link')}`)+`<div class="metric-grid">${metric('Зарегистрировано',e.guests.registered,'Заявки через страницу события','users')}${metric('Подтверждено',s.data.guests.filter(g=>['confirmed','attended'].includes(g.status)).length,'Участники подтвердили участие','check','green')}${metric('Пришли на событие',e.guests.attended,'Отмечены на входе','qr','orange')}${metric('Свободных мест',Math.max(0,e.capacity-e.guests.registered),'Регистрация '+(e.registration_open?'открыта':'закрыта'),'calendar','blue')}</div><div class="toolbar">${tabs([['all','Все гости'],['registered','Новые'],['confirmed','Подтверждены'],['attended','Пришли'],['cancelled','Отменены']])}<div class="heading-actions">${searchBox(isOrg()?'Имя, почта, организация':'Имя или организация')}${isOrg()?`<a class="button secondary" href="/api/events/${e.id}/guests.csv" aria-label="Скачать участников CSV">${icon('download')} CSV</a>`:''}</div></div><div class="panel">${guests.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Участник</th>${isOrg()?'<th>Контакты</th>':''}<th>Организация</th><th>Статус</th>${isOrg()?'<th>Билет</th>':''}</tr></thead><tbody>${guests.map((g,i)=>`<tr><td>${avatar(g.name,i)}<strong>${esc(g.name)}</strong></td>${isOrg()?`<td>${esc(g.email)}${g.phone?`<small>${esc(g.phone)}</small>`:''}</td>`:''}<td>${esc(g.company||'—')}</td><td>${isOrg()?`<select class="status-select" data-change="guest-status" data-id="${g.id}" data-attended="${g.status==='attended'?1:''}" aria-label="Статус гостя ${esc(g.name)}">${[...(g.status==='attended'?['attended']:[]),'registered','confirmed','cancelled'].map(x=>`<option value="${x}" ${x===g.status?'selected':''}>${labels[x]}</option>`).join('')}</select>`:badge(g.status)}</td>${isOrg()?`<td><button class="text-button" data-action="ticket" data-ticket="${g.ticket}">${icon('qr')} Билет</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Первые гости ещё впереди','Поделитесь ссылкой на страницу регистрации.')}</div>`;}
function teamView(){const people=s.data.team.filter(p=>matches(p.name,p.role,p.service)&&(s.filter==='all'||p.kind===s.filter));return pageHeading('Команда и подрядчики','Люди, благодаря которым всё получится.',isOrg()?button('Добавить участника','new-person'): '')+`<div class="toolbar">${tabs([['all','Все'],['team','Команда'],['contractor','Подрядчики']])}${searchBox('Найти человека или компанию')}</div><div class="team-cards">${people.map((p,i)=>{const tasks=s.data.tasks.filter(t=>t.assignee_id===p.id),done=tasks.filter(t=>t.status==='done').length;return `<article class="person-card"><div class="person-card-top">${avatar(p.name,i)}${p.kind==='contractor'?badge(p.status,p.status==='active'?'В работе':p.status==='done'?'Выполнено':'Обсуждение'):badge('planning','Команда')}${isOrg()?`<button class="icon-button" data-action="edit-person" data-id="${p.id}" aria-label="Изменить ${esc(p.name)}">${icon('edit')}</button>`:''}</div><h3>${esc(p.name)}</h3><p>${esc(p.role)}</p>${p.service?`<p>${esc(p.service)}${isOrg()?' · '+money(p.cost):''}</p>`:''}<hr><div class="contact">${icon('mail')}${p.email?`<a href="mailto:${esc(p.email)}">${esc(p.email)}</a>`:'<span class="muted">Почта не указана</span>'}</div>${p.phone?`<p class="contact">${icon('phone')}${esc(p.phone)}</p>`:''}<div class="toolbar" style="margin:18px 0 6px;font-size:10px;color:var(--muted)"><span>Выполнено задач</span><strong>${done} / ${tasks.length}</strong></div><div class="progress-track"><i style="width:${tasks.length?done/tasks.length*100:0}%"></i></div></article>`;}).join('')||empty('Никого не нашли','Измените поиск или добавьте участника.')}</div>`;}
function filesView(){const files=s.data.files.filter(f=>matches(f.name,f.task_title));return pageHeading('Файлы события','Материалы и документы, которые всегда под рукой.')+`<button class="upload-zone" data-action="upload">${icon('upload')}<span>Выберите файл для загрузки<small>Документы, изображения и архивы · до 4 ГБ</small></span></button><div class="toolbar"><span class="muted small">${s.data.files.length} файлов в пространстве</span>${searchBox('Найти файл')}</div><div class="panel">${files.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Название</th><th>Задача</th><th>Кто загрузил</th><th>Размер</th><th></th></tr></thead><tbody>${files.map(f=>`<tr><td><div class="file-cell"><span class="file-type">${esc(f.name.split('.').pop().slice(0,4).toUpperCase())}</span><strong>${esc(f.name)}</strong></div></td><td>${esc(f.task_title||'Общие материалы')}</td><td>${esc(f.author.split(' ')[0])}<small>${activityTime(f.created_at)}</small></td><td>${sizeLabel(f.size)}</td><td><div class="row-actions"><a class="icon-button" href="/api/files/${f.id}" aria-label="Скачать ${esc(f.name)}">${icon('download')}</a>${isOrg()||f.created_by===s.user.id?`<button class="icon-button" data-action="delete-file" data-id="${f.id}" aria-label="Удалить файл">${icon('trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Чистый лист для ваших материалов','Загрузите бриф, макет или смету. Файл можно связать с задачей.')}</div>`;}
function sizeLabel(n){return n>=1073741824?(n/1073741824).toFixed(2)+' ГБ':n>=1048576?(n/1048576).toFixed(1)+' МБ':n>=1024?(n/1024).toFixed(1)+' КБ':n+' Б';}
function budgetView(){const e=s.data.event;return pageHeading('Бюджет','Планируйте расходы и держите фактические затраты под контролем.',isOrg()?button('Добавить расход','new-expense'):'')+(e.expense.actual>e.budget?`<div class="alert">Бюджет превышен на ${money(e.expense.actual-e.budget)}. Проверьте статьи расходов.</div>`:e.expense.planned>e.budget?`<div class="alert">Плановые расходы превышают бюджет на ${money(e.expense.planned-e.budget)}.</div>`:'')+`<div class="metric-grid">${metric('Бюджет события',money(e.budget),'Установлен организатором','wallet')}${metric('Плановые расходы',money(e.expense.planned),'Сумма всех статей','tasks','blue')}${metric('Фактические расходы',money(e.expense.actual),'Уже потрачено','chart','orange')}${metric('Остаток',money(e.budget-e.expense.actual),`${Math.round(e.expense.actual/Math.max(e.budget,1)*100)}% бюджета использовано`,'check','green')}</div><div class="panel"><div class="panel-head"><h2>Статьи расходов</h2>${isOrg()?`<a class="text-button" href="/api/events/${e.id}/budget.csv">${icon('download')} Скачать CSV</a>`:''}</div>${s.data.expenses.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Статья расходов</th><th>Категория</th><th>План</th><th>Факт</th><th>Разница</th><th></th></tr></thead><tbody>${s.data.expenses.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td><span class="muted">${esc(x.category)}</span></td><td>${money(x.planned)}</td><td>${money(x.actual)}</td><td class="${x.actual>x.planned?'negative':'positive'}">${money(x.planned-x.actual)}</td><td>${isOrg()?`<button class="icon-button" data-action="edit-expense" data-id="${x.id}" aria-label="Изменить расход ${esc(x.name)}">${icon('edit')}</button>`:''}</td></tr>`).join('')}<tr class="budget-total"><td colspan="2">Итого</td><td>${money(e.expense.planned)}</td><td>${money(e.expense.actual)}</td><td>${money(e.expense.planned-e.expense.actual)}</td><td></td></tr></tbody></table></div>`:empty('Расходов пока нет','Добавьте статьи расходов и укажите плановые суммы.')}</div>`;}
function calendarView(){const [year,month]=s.month.split('-').map(Number);const first=new Date(year,month-1,1),offset=(first.getDay()+6)%7;let cells='';for(let i=0;i<42;i++){const d=new Date(year,month-1,1-offset+i),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const events=s.events.filter(e=>e.starts_at.startsWith(key));const tasks=s.data.tasks.filter(t=>t.due_date===key&&t.status!=='done');cells+=`<div class="calendar-day ${d.getMonth()!==month-1?'dim':''} ${key===today()?'today':''}"><span class="day-number">${d.getDate()}</span>${events.map(e=>`<button class="calendar-event" title="${esc(e.title)}" data-action="open-event" data-id="${e.id}">${esc(e.title)}</button>`).join('')}${tasks.map(t=>`<button class="calendar-event task" title="${esc(t.title)}" data-action="task" data-id="${t.id}">${esc(t.title)}</button>`).join('')}</div>`;}return pageHeading('Календарь','События и сроки задач текущего мероприятия.')+`<div class="panel pad"><div class="calendar-head"><h2>${first.toLocaleDateString('ru-RU',{month:'long'})} ${year}</h2><div class="heading-actions"><button class="button secondary slim" data-action="month-today">Сегодня</button><button class="icon-button" data-action="month" data-delta="-1" aria-label="Предыдущий месяц">${icon('left')}</button><button class="icon-button" data-action="month" data-delta="1" aria-label="Следующий месяц">${icon('chevron')}</button></div></div><div class="legend" style="margin-bottom:15px"><span><i></i>Мероприятия</span><span><i class="orange"></i>Сроки задач</span></div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells}</div></div>`;}
const surveyStatus={draft:['todo','Черновик'],open:['done','Приём ответов открыт'],closed:['finished','Опрос закрыт']};
const surveyKinds={rating:'Оценка 1–5',choice:'Выбор варианта',text:'Свободный ответ'};
function surveyView(){return `<div id="survey-root">${pageHeading('Опрос гостей','Соберите обратную связь после мероприятия.')}<div class="panel pad muted">Загружаем опрос…</div></div>`;}
async function loadSurvey(){const eventId=s.eventId;try{const data=await api(`/events/${eventId}/survey`);if(s.view!=='survey'||s.eventId!==eventId)return;s.survey={eventId,...data};const root=$('#survey-root');if(root)root.innerHTML=surveyBody(s.survey);}catch(error){const root=$('#survey-root');if(root)root.innerHTML=pageHeading('Опрос гостей')+`<div class="panel">${empty('Не удалось загрузить опрос',error.message)}</div>`;}}
function surveyBody(d){if(!d.survey)return pageHeading('Опрос гостей','Соберите обратную связь после мероприятия.')+`<div class="panel">${empty('Опроса пока нет','Создайте короткую анкету: оценка, что понравилось и что улучшить. Ссылку на неё гости увидят в своём билете.',button('Создать опрос','new-survey'))}</div>`;
 const sv=d.survey,[cls,label]=surveyStatus[sv.status],attended=s.data.event.guests.attended,url=location.origin+'/survey/'+sv.public_token;
 const toggle=sv.status==='open'?button('Закрыть приём','survey-status','lock','secondary','data-status="closed"'):button(sv.status==='draft'?'Открыть приём ответов':'Открыть снова','survey-status','check','','data-status="open"');
 return pageHeading(sv.title,sv.description||'Обратная связь от гостей мероприятия.',`${button('Изменить','edit-survey','edit','secondary')}${toggle}`)
 +`<div class="panel pad survey-share"><div>${badge(cls,label)}<p class="small muted">${sv.status==='draft'?'Гости пока не видят опрос. Откройте приём ответов, когда мероприятие закончится.':sv.status==='open'?'Ссылка на опрос показывается в билете каждого гостя. Её можно отправить и отдельно.':'Новые ответы не принимаются. Результаты сохранены.'}</p></div>${sv.status!=='draft'?`<div class="survey-link"><input readonly value="${esc(url)}" aria-label="Ссылка на опрос">${button('Скопировать','copy-survey','copy','secondary')}</div>`:''}</div>`
 +`<div class="metric-grid section-gap">${metric('Ответов',d.responses,attended?`${Math.round(d.responses/attended*100)}% от пришедших гостей`:'Гости ещё не отмечены на входе','users','green')}${metric('Средняя оценка',d.average===null?'—':String(d.average).replace('.',',')+' из 5','По первому вопросу с оценкой','check')}${metric('Вопросов',d.questions.length,'Обязательных: '+d.questions.filter(q=>q.required).length,'tasks','orange')}</div>`
 +(d.responses?d.questions.map(surveyResult).join(''):`<div class="panel section-gap">${empty('Ответов пока нет',sv.status==='open'?'Результаты появятся здесь, как только гости заполнят анкету.':'Откройте приём ответов, чтобы гости могли заполнить анкету.')}</div>`)
 +`<div class="section-gap">${button('Удалить опрос','delete-survey','trash','danger')}</div>`;}
function surveyResult(q){const head=`<h2>${esc(q.text)}</h2><p class="small muted">${surveyKinds[q.kind]} · ответов: ${q.answers}</p>`;
 if(q.kind==='rating'){const max=Math.max(...q.counts,1);return `<section class="panel pad section-gap survey-result"><div class="survey-result-head"><div>${head}</div><strong class="survey-score">${q.average===null?'—':String(q.average).replace('.',',')}</strong></div>${[5,4,3,2,1].map(n=>`<div class="chart-row"><span>${'★'.repeat(n)}</span><div class="progress-track"><i style="width:${q.counts[n-1]/max*100}%"></i></div><strong>${q.counts[n-1]}</strong></div>`).join('')}</section>`;}
 if(q.kind==='choice'){const max=Math.max(...q.counts,1);return `<section class="panel pad section-gap survey-result">${head}${q.options.map((o,i)=>`<div class="chart-row"><span>${esc(o)}</span><div class="progress-track"><i style="width:${q.counts[i]/max*100}%;background:var(--orange)"></i></div><strong>${q.counts[i]}</strong></div>`).join('')}</section>`;}
 return `<section class="panel pad section-gap survey-result">${head}${q.texts.length?`<ul class="survey-quotes">${q.texts.map(t=>`<li><p>${esc(t.value)}</p><span>${esc(activityTime(t.created_at))}</span></li>`).join('')}</ul>`:'<p class="small muted">Пока никто не ответил.</p>'}</section>`;}
function surveyTemplate(){const titles=(s.data.program||[]).map(p=>p.title).slice(0,8);return {title:'Как прошло мероприятие?',description:'Спасибо, что были с нами! Ответьте на три вопроса — это займёт минуту.',questions:[{text:'Оцените мероприятие в целом',kind:'rating',options:[],required:true},{text:'Что понравилось больше всего?',kind:'choice',options:titles.length>=2?titles:['Программа','Спикеры','Организация','Нетворкинг'],required:false},{text:'Что нам улучшить в следующий раз?',kind:'text',options:[],required:false}]};}
function surveyQuestionBlock(q,i){return `<div class="survey-q" data-kind="${q.kind}" ${q.id?`data-id="${q.id}"`:''}><div class="survey-q-head"><strong>Вопрос ${i+1}</strong><button type="button" class="icon-button" data-action="survey-remove-q" data-index="${i}" aria-label="Удалить вопрос ${i+1}">${icon('trash')}</button></div><label class="field"><span>Текст вопроса</span><input data-q="text" required maxlength="500" value="${esc(q.text)}"></label><div class="form-grid"><label class="field"><span>Тип ответа</span><select data-q="kind">${Object.entries(surveyKinds).map(([k,l])=>`<option value="${k}" ${q.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="checkbox-line survey-required"><input type="checkbox" data-q="required" ${q.required?'checked':''}> Обязательный</label></div><label class="field q-options"><span>Варианты ответа — каждый с новой строки</span><textarea data-q="options" maxlength="4000">${esc((q.options||[]).join('\n'))}</textarea></label></div>`;}
function readSurveyQuestions(){return [...document.querySelectorAll('#survey-questions .survey-q')].map(el=>({...(el.dataset.id?{id:Number(el.dataset.id)}:{}),text:el.querySelector('[data-q=text]').value,kind:el.querySelector('[data-q=kind]').value,options:el.querySelector('[data-q=options]').value.split('\n').map(x=>x.trim()).filter(Boolean),required:el.querySelector('[data-q=required]').checked}));}
function renderSurveyQuestions(list){$('#survey-questions').innerHTML=list.map(surveyQuestionBlock).join('');}
function surveyForm(){const d=s.survey?.survey?{...s.survey.survey,questions:s.survey.questions}:surveyTemplate();openModal(s.survey?.survey?'Изменить опрос':'Новый опрос',`${field('Название','title',d.title,'text',{max:200})}${field('Обращение к гостям','description',d.description||'','textarea',{required:false,max:2000})}<div id="survey-questions" class="survey-questions"></div>${button('Добавить вопрос','survey-add-q','plus','secondary','type="button"')}${s.survey?.responses?'<p class="small muted section-gap">Если удалить вопрос, ответы на него тоже удалятся.</p>':''}`,{submit:'Сохранить',wide:true,onSubmit:async form=>{const p=formObject(form);const result=await api(`/events/${s.eventId}/survey`,'PUT',{title:p.title,description:p.description,status:d.status||'draft',questions:readSurveyQuestions()});s.survey={eventId:s.eventId,...result};await reload();toast('Опрос сохранён');}});renderSurveyQuestions(d.questions);}
async function surveyPage(token){let d;try{d=await api('/survey/'+token);}catch(e){return publicError(e.message);}const ticket=new URLSearchParams(location.search).get('ticket')||'';const sv=d.survey;
 const control=q=>q.kind==='rating'?`<div class="rating-scale" role="radiogroup" aria-label="${esc(q.text)}">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="q${q.id}" value="${n}" ${q.required?'required':''}><span>${n}</span></label>`).join('')}</div><div class="rating-hint"><span>Плохо</span><span>Отлично</span></div>`:q.kind==='choice'?`<div class="choice-list">${q.options.map(o=>`<label class="checkbox-line"><input type="radio" name="q${q.id}" value="${esc(o)}" ${q.required?'required':''}> ${esc(o)}</label>`).join('')}</div>`:`<textarea name="q${q.id}" maxlength="2000" ${q.required?'required':''} placeholder="Ваш ответ"></textarea>`;
 $('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand('/afisha')}<a class="text-button" href="/afisha">${icon('left')} Афиша</a></div><section class="panel pad survey-public"><p class="eyebrow">${esc(sv.event_title)}</p><h1>${esc(sv.title)}</h1>${sv.description?`<p class="muted">${esc(sv.description)}</p>`:''}${sv.status!=='open'?`<div class="section-gap">${empty('Опрос закрыт','Организатор больше не принимает ответы. Спасибо за интерес!')}</div>`:`<form id="survey-form" data-token="${token}" data-ticket="${esc(ticket)}">${d.questions.map((q,i)=>`<fieldset class="survey-field"><legend>${i+1}. ${esc(q.text)}${q.required?' <span class="req">*</span>':''}</legend>${control(q)}</fieldset>`).join('')}<p class="form-error" role="alert"></p><button class="button" type="submit">Отправить ответы</button></form>`}</section></main>`;}
function surveyThanks(){$('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand('/afisha')}<a class="text-button" href="/my-tickets">${icon('qr')} Мои билеты</a></div><section class="panel pad survey-public">${empty('Спасибо за ответы!','Ваше мнение поможет сделать следующее мероприятие ещё лучше.',`<a class="button" href="/afisha">${icon('calendar')} Другие мероприятия</a>`)}</section></main>`;}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='survey-form')return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;form.querySelector('.form-error').textContent='';try{const answers={};for(const [key,value] of new FormData(form))if(key.startsWith('q'))answers[key.slice(1)]=value;await api('/survey/'+form.dataset.token,'POST',{answers,ticket:form.dataset.ticket});surveyThanks();}catch(error){form.querySelector('.form-error').textContent=error.message;}finally{submit.disabled=false;}});
document.addEventListener('change',event=>{const select=event.target.closest?.('[data-q=kind]');if(select)select.closest('.survey-q').dataset.kind=select.value;});
function analyticsView(){const e=s.data.event,ratio=e.guests.registered?Math.round(e.guests.attended/e.guests.registered*100):0;return pageHeading('Аналитика','Состояние подготовки и результаты в цифрах.',isOrg()?`<a class="button secondary" href="/api/events/${e.id}/report.json">${icon('download')} Отчёт</a>`:'')+`<div class="metric-grid">${metric('Готовность события',e.readiness+'%',`${e.tasks.done} задач из ${e.tasks.total} выполнено`,'check')}${metric('Посещаемость',ratio+'%',`${e.guests.attended} пришли из ${e.guests.registered} зарегистрированных`,'users','green')}${metric('Расход на гостя',money(e.guests.registered?e.expense.actual/e.guests.registered:0),'Фактические расходы / регистрации','wallet','orange')}${metric('Просрочено задач',e.tasks.overdue,'Незавершённые задачи с истёкшим сроком','clock','blue')}${s.data.survey?metric('Опрос гостей',s.data.survey.average===null?'—':String(s.data.survey.average).replace('.',',')+'/5',`${plural(s.data.survey.responses,'ответ','ответа','ответов')} · ${surveyStatus[s.data.survey.status]?.[1]||s.data.survey.status}`,'poll'):''}</div><div class="grid-main"><section class="panel pad"><h2>Задачи по статусам</h2><p class="small muted" style="margin-top:5px">Текущее состояние подготовки</p><div class="chart-column">${[['todo','Ожидание','orange'],['progress','В работе',''],['done','Готово','lime']].map(([key,label,cls])=>{const n=s.data.tasks.filter(t=>t.status===key).length;return `<div><b>${n}</b><div class="bar ${cls}" style="height:${Math.max(2,n/Math.max(e.tasks.total,1)*140)}px"></div><label>${label}</label></div>`;}).join('')}</div></section><section class="panel pad"><h2>Гости события</h2>${[['Зарегистрированы',e.guests.registered],['План участников',e.capacity],['Пришли на событие',e.guests.attended]].map(([label,n])=>`<div class="chart-row"><span>${label}</span><div class="progress-track"><i style="width:${n/Math.max(e.capacity,e.guests.registered,1)*100}%"></i></div><strong>${n}</strong></div>`).join('')}<p class="small muted">Посещаемость обновляется после проверки билетов на входе.</p></section></div><section class="panel pad section-gap"><h2>Расходы по категориям</h2>${s.data.expenses.length?s.data.expenses.map(x=>`<div class="chart-row"><span>${esc(x.name)}</span><div class="progress-track"><i style="width:${x.actual/Math.max(e.expense.actual,1)*100}%;background:var(--orange)"></i></div><strong style="font-size:10px;white-space:nowrap">${money(x.actual)}</strong></div>`).join(''):empty('Нет данных о расходах','Добавьте фактические расходы в разделе «Бюджет».')}</section>`;}

function eventForm(id){const e=id?s.events.find(x=>x.id===Number(id)):{};openModal(id?'Параметры мероприятия':'Новое мероприятие',`<div class="form-grid">${field('Название','title',e.title,'text',{full:true,max:160,placeholder:'Например, IT-Форум 2026'})}${field('Тип мероприятия','type',e.type||'Форум','select',{options:['Форум','Конференция','Встреча','Хакатон','Фестиваль','Корпоративное событие','Другое'].map(x=>[x,x])})}${field('Дата и время · Якутск','starts_at',e.starts_at||'2026-11-20T10:00','datetime-local')}${field('Место или ссылка на онлайн-площадку','location',e.location,'text',{full:true,placeholder:'Адрес площадки или ссылка'})}${field('Описание','description',e.description,'textarea',{full:true,required:false,max:5000})}${field('Цель мероприятия','goal',e.goal,'textarea',{full:true,required:false,max:2000})}${field('Количество участников','capacity',e.capacity||100,'number',{min:1})}${field('Общий бюджет, ₽','budget',e.budget??0,'number',{step:'0.01'})}${field('Статус','status',e.status||'planning','select',{options:['planning','active','finished'].map(x=>[x,labels[x]])})}<label class="checkbox-line" style="align-self:center"><input name="registration_open" type="checkbox" ${e.registration_open===0?'':'checked'}>Регистрация гостей открыта</label></div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-event" data-id="${e.id}">${icon('trash')} Удалить мероприятие</button>`:'<p class="small muted" style="margin-top:15px">Вы станете ответственным организатором. Команду можно добавить после создания.</p>'}`,{submit:id?'Сохранить':'Создать мероприятие',onSubmit:async form=>{const p=formObject(form);p.capacity=Number(p.capacity);p.budget=Number(p.budget);p.registration_open=form.registration_open.checked;const result=await api('/events'+(id?'/'+id:''),id?'PATCH':'POST',p);if(!id){s.eventId=result.id;s.view='overview';location.hash='overview';}closeModal();await reload();toast(id?'Мероприятие обновлено':'Мероприятие создано');}});}
function taskForm(id){const t=id?s.data.tasks.find(x=>x.id===Number(id)):{};openModal(id?'Редактировать задачу':'Новая задача',`<div class="form-grid">${field('Название задачи','title',t.title,'text',{full:true,max:200,placeholder:'Что нужно сделать?'})}${field('Описание','description',t.description,'textarea',{full:true,required:false})}${field('Ответственный','assignee_id',t.assignee_id||'','select',{required:false,options:[['','Не назначен'],...s.data.team.map(p=>[p.id,p.name])]})}${field('Срок выполнения','due_date',t.due_date||s.data.event.starts_at.slice(0,10),'date')}${field('Приоритет','priority',t.priority||'normal','select',{options:[['low','Низкий'],['normal','Обычный'],['high','Высокий']]})}${field('Статус','status',t.status||'todo','select',{options:['todo','progress','done'].map(x=>[x,labels[x]])})}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-task" data-id="${id}">${icon('trash')} Удалить задачу</button>`:''}`,{submit:id?'Сохранить':'Добавить задачу',onSubmit:async form=>{const p=formObject(form);p.assignee_id=Number(p.assignee_id)||null;await saved(id?'/tasks/'+id:'/events/'+s.eventId+'/tasks',id?'PATCH':'POST',p,id?'Задача обновлена':'Задача добавлена');}});}
async function taskDetail(id){const t=s.data.tasks.find(x=>x.id===Number(id));if(!t)return;const comments=await api('/tasks/'+id+'/comments');const canWrite=isOrg()||t.assignee_user_id===s.user.id;const attached=s.data.files.filter(f=>f.task_id===t.id);openModal(t.title,`<div class="detail-meta">${badge(t.status)}${priority(t.priority)}<span class="muted">${dateShort(t.due_date)}</span></div><p class="task-detail-description">${esc(t.description||'Описание пока не добавлено.')}</p><div class="detail-meta">${avatar(t.assignee_name||'?')}<span>${esc(t.assignee_name||'Ответственный не назначен')}</span>${isOrg()?`<button type="button" class="text-button" data-action="edit-task" data-id="${t.id}">${icon('edit')} Изменить</button>`:''}</div><div class="divider"></div><div class="toolbar"><h3>Вложения</h3>${canWrite?`<button type="button" class="text-button" data-action="upload" data-task="${t.id}">${icon('upload')} Добавить файл</button>`:''}</div>${attached.map(f=>`<p style="margin-top:8px;font-size:12px"><a href="/api/files/${f.id}">${icon('file')} ${esc(f.name)}</a></p>`).join('')||'<p class="small muted">Вложений пока нет.</p>'}<div class="divider"></div><h3>Комментарии · ${comments.length}</h3><div class="comment-list">${comments.map(c=>`<div class="comment">${avatar(c.author,c.user_id)}<div><strong>${esc(c.author)}</strong> <small>${activityTime(c.created_at)}</small><p>${esc(c.text)}</p></div></div>`).join('')||'<p class="small muted">Обсудите детали задачи с командой.</p>'}</div>${canWrite?field('Ваш комментарий','text','','textarea',{placeholder:'Напишите о ходе работы…',max:3000}):'<p class="notice">Изменять задачу и оставлять комментарии может её ответственный.</p>'}`,{submit:'Отправить комментарий',onSubmit:canWrite?async form=>{await api('/tasks/'+id+'/comments','POST',formObject(form));await reload(false);await taskDetail(id);toast('Комментарий добавлен');return false;}:null});}
function expenseForm(id){const x=id?s.data.expenses.find(x=>x.id===Number(id)):{};openModal(id?'Редактировать расход':'Новая статья расходов',`<div class="form-grid">${field('Название статьи','name',x.name,'text',{full:true,max:200})}${field('Категория','category',x.category||'Площадка','select',{full:true,options:['Площадка','Кейтеринг','Оборудование','Транспорт','Проживание','Полиграфия','Реклама','Подрядчики','Призы','Другое'].map(x=>[x,x])})}${field('Плановая сумма, ₽','planned',x.planned??0,'number',{step:'0.01'})}${field('Фактическая сумма, ₽','actual',x.actual??0,'number',{step:'0.01'})}</div>${id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-expense" data-id="${id}">${icon('trash')} Удалить статью</button>`:''}`,{submit:id?'Сохранить':'Добавить расход',onSubmit:async form=>{const p=formObject(form);p.planned=Number(p.planned);p.actual=Number(p.actual);await saved(id?'/expenses/'+id:'/events/'+s.eventId+'/expenses',id?'PATCH':'POST',p);}});}
function personForm(id){const p=id?s.data.team.find(x=>x.id===Number(id)):{};openModal(id?'Участник команды':'Добавить в команду',`<div class="form-grid">${field('Имя или название компании','name',p.name,'text',{full:true,max:120})}${field('Тип','kind',p.kind||'team','select',{options:[['team','Участник команды'],['contractor','Подрядчик']]})}${field('Роль / зона ответственности','role',p.role,'text',{max:120})}${field('Электронная почта','email',p.email,'email',{required:false,max:200})}${field('Телефон','phone',p.phone,'tel',{required:false,max:40})}${field('Услуга подрядчика','service',p.service,'text',{full:true,required:false})}${field('Стоимость услуги, ₽','cost',p.cost??0,'number',{step:'0.01'})}${field('Статус взаимодействия','status',p.status||'active','select',{options:[['active','В работе'],['pending','Обсуждение'],['done','Выполнено']]})}</div><p class="small muted" style="margin-top:15px">Для доступа через аккаунт команды укажите team@eventgo.local. Другие контакты хранятся в карточке без создания учётной записи.</p>${id&&p.user_id!==s.user.id?`<div class="divider"></div><button type="button" class="text-button negative" data-action="delete-person" data-id="${id}">${icon('trash')} Удалить участника</button>`:''}`,{submit:id?'Сохранить':'Добавить участника',onSubmit:async form=>{const data=formObject(form);data.cost=Number(data.cost);await saved(id?'/team/'+id:'/events/'+s.eventId+'/team',id?'PATCH':'POST',data);}});}
function confirmDelete(type,id,label){openModal('Удалить '+label+'?',`<p class="muted" style="font-size:13px">${type==='events'?'Мероприятие, задачи, гости, расходы и файлы будут удалены.':'Запись будет удалена из мероприятия.'} Это действие нельзя отменить в интерфейсе.</p>`,{submit:'Удалить',onSubmit:async()=>{await api('/'+type+'/'+id,'DELETE');closeModal();if(type==='events'){s.view='events';location.hash='events';}await reload();toast('Удалено');}});}
function registration(){const e=s.data.event,url=location.origin+'/register/'+e.public_token;openModal('Регистрация на мероприятие',`<p class="muted" style="margin-bottom:18px;font-size:13px">Поделитесь ссылкой с гостями. После заполнения формы участник получит личный билет.</p><p style="margin-bottom:18px">${badge(e.registration_open&&e.status!=='finished'?'done':'finished',e.registration_open&&e.status!=='finished'?'Регистрация открыта':'Регистрация закрыта')}</p><label class="field"><span>Ссылка для гостей</span><input readonly value="${esc(url)}" aria-label="Ссылка регистрации"></label><div class="heading-actions" style="justify-content:flex-start;margin-top:20px;flex-wrap:wrap">${button('Скопировать','copy-registration','copy')}<a class="button secondary" href="${url}" target="_blank" rel="noopener">${icon('external')} Открыть страницу</a>${isOrg()?button(e.registration_open?'Закрыть регистрацию':'Открыть регистрацию','toggle-registration',e.registration_open?'lock':'check','secondary'):''}</div><p class="small muted" style="margin-top:18px">Ссылка доступна на этом компьютере. Для других устройств используйте режим локальной сети из инструкции.</p>`);}
async function ticketModal(code){const t=await api('/ticket/'+code);openModal('Входной билет',`<div class="ticket-content"><h3>${esc(t.title)}</h3><p class="muted small">${esc(t.name)}</p><div class="ticket-qr">${qrSvg('EG:'+t.ticket)}</div>${badge(t.status)}<p class="ticket-code">EG:${t.ticket}</p><a class="button secondary" href="/ticket/${t.ticket}" target="_blank" rel="noopener">${icon('external')} Открыть билет</a></div>`);}
function upload(taskId){
 openModal('Загрузить файл',`<div class="form-grid"><label class="field full"><span>Файл · до 4 ГБ *</span><input name="file" type="file" required></label>${field('Связать с задачей','task_id',taskId||'','select',{full:true,required:false,options:[['','Общие материалы'],...s.data.tasks.map(t=>[t.id,t.title])]})}</div><div id="upload-progress" class="upload-progress" hidden><progress max="100" value="0" aria-label="Ход загрузки"></progress><p class="small muted" role="status"></p></div><p class="small muted" style="margin-top:15px">Для больших файлов оставьте окно открытым до завершения загрузки.</p>`,{submit:'Загрузить',onSubmit:async form=>{
   const file=form.file.files[0];if(file.size>MAX_FILE_BYTES)throw new Error('Максимальный размер файла — 4 ГБ (4 294 967 296 байт).');
   const url=`/api/events/${s.eventId}/files?name=${encodeURIComponent(file.name)}&task_id=${encodeURIComponent(form.task_id.value)}`;
   await new Promise((resolve,reject)=>{
     const xhr=new XMLHttpRequest();xhr.open('POST',url);xhr.timeout=2*60*60*1000;xhr.setRequestHeader('X-EventGo','1');xhr.setRequestHeader('Content-Type','application/octet-stream');
     cleanupModal=()=>{if(xhr.readyState!==4)xhr.abort();};
     const box=$('#upload-progress');box.hidden=false;
     xhr.upload.onprogress=event=>{const total=event.total||file.size;box.querySelector('progress').value=total?event.loaded/total*100:0;box.querySelector('p').textContent=event.loaded===total?'Сохраняем файл…':`Передано ${sizeLabel(event.loaded)} из ${sizeLabel(total)}`;};
     xhr.onload=()=>{cleanupModal=null;let data;try{data=JSON.parse(xhr.responseText);}catch{}if(xhr.status>=200&&xhr.status<300)resolve(data);else reject(new Error(data?.error||'Не удалось загрузить файл.'));};
     xhr.onerror=()=>{cleanupModal=null;reject(new Error('Связь с сервером прервалась. Повторите загрузку.'));};
     xhr.ontimeout=()=>{cleanupModal=null;reject(new Error('Время загрузки истекло. Повторите попытку.'));};
     xhr.onabort=()=>reject(new Error('Загрузка отменена.'));xhr.send(file);
   });
   closeModal();await reload();toast('Файл загружен');
 }});
}
function checkin(){openModal('Проверить билет',`<p class="muted small" style="margin-bottom:20px">Отсканируйте QR или вставьте код с билета. Повторный вход и отменённые билеты будут отклонены.</p>${field('Код билета или ссылка','ticket','','text',{placeholder:'EG:…',max:300})}<div id="camera"></div><button type="button" class="text-button" style="margin-top:15px" data-action="camera">${icon('qr')} Сканировать камерой</button><p class="small muted" style="margin-top:12px">Проверка для события: ${esc(s.data.event.title)}</p>`,{submit:'Проверить и отметить вход',onSubmit:async form=>{const result=await api('/events/'+s.eventId+'/checkin','POST',formObject(form));closeModal();await reload();toast('Вход отмечен: '+result.name);}});}
async function scanCamera(){if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){toast('Этот браузер не поддерживает сканирование. Вставьте код с билета.',true);return;}const detector=new BarcodeDetector({formats:['qr_code']});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const container=$('#camera');if(!container){stream.getTracks().forEach(t=>t.stop());return;}container.innerHTML='<video class="video-preview" autoplay muted playsinline aria-label="Камера для сканирования QR"></video>';const video=container.querySelector('video');video.srcObject=stream;let stopped=false;cleanupModal=()=>{stopped=true;stream.getTracks().forEach(t=>t.stop());};await video.play();const tick=async()=>{if(stopped)return;try{const codes=await detector.detect(video);if(codes.length){$('#modal-form').ticket.value=codes[0].rawValue;cleanupModal();cleanupModal=null;container.innerHTML='<p class="notice">Код считан. Нажмите «Проверить и отметить вход».</p>';return;}}catch{}if(!stopped)setTimeout(tick,300);};tick();}
function profile(){openModal('Ваш аккаунт',`<div style="display:flex;align-items:center;gap:12px">${avatar(s.user.name)}<div><h3>${esc(s.user.name)}</h3><p class="small muted">${esc(s.user.email)} · ${isOrg()?'Организатор':'Участник команды'}</p></div></div><div class="divider"></div><div class="stack" style="gap:12px;align-items:flex-start">${button('Изменить пароль','password','lock','secondary')}${isOrg()?'<a class="button secondary" href="/api/backup">'+icon('download')+' Скачать копию базы</a>':''}${button('Выйти из аккаунта','logout','logout','secondary')}</div><p class="small muted" style="margin-top:20px">В копию базы входят записи и учётные записи. Для полного переноса файлов скопируйте папку yba целиком после остановки сервера.</p>`);}
function passwordForm(){openModal('Изменить пароль',`<div class="form-grid">${field('Текущий пароль','current','','password',{full:true})}${field('Новый пароль','password','','password',{full:true,hint:'Не менее 10 символов'})}</div>`,{submit:'Изменить пароль',onSubmit:async form=>{await api('/password','POST',formObject(form));closeModal();s.user=null;renderLogin();toast('Пароль изменён. Войдите снова.');}});}
function renderLogin(){teamChat.stop();aiAssistant.stop();closeModal();$('#app').innerHTML=`<main class="login-page"><section class="login-story">${brand()}<div class="login-copy"><h1>Больше, чем<br><em>события.</em></h1><p>Идеи становятся событиями, когда у команды есть общее пространство.</p><div class="login-mini-card"><h3>${icon('check')} Всё о событии в одном месте</h3><div class="login-mini-stats"><div><strong>Задачи</strong><span>сроки и ответственные</span></div><div><strong>Гости</strong><span>регистрация и QR</span></div><div><strong>Бюджет</strong><span>план и факт</span></div></div></div></div><p class="login-tag">ПЛАНИРУЙТЕ. ОБЪЕДИНЯЙТЕ. СОЗДАВАЙТЕ.</p></section><section class="login-form-side"><div class="login-form-wrap"><h2>Рады видеть вас</h2><p>Войдите, чтобы продолжить подготовку.</p><form id="login-form">${field('Электронная почта','email','','email',{placeholder:'you@example.com',max:200})}${field('Пароль','password','','password',{placeholder:'Введите пароль',max:200})}<p class="form-error" role="alert"></p><button class="button" type="submit">Войти в пространство ${icon('arrow')}</button></form><div class="demo-box"><p>Первый раз здесь? Посмотрите готовый пример.</p><div class="demo-buttons">${button('Я организатор','demo-organizer','grid','soft')}${button('Я в команде','demo-member','team','secondary')}</div><a class="button secondary guest-entry" href="/afisha">${icon('users')} Я гость — афиша мероприятий ${icon('arrow')}</a></div><p class="login-caption">Демонстрационные аккаунты и данные подготовлены для знакомства с сервисом. Работает локально, без подключения к внешним сервисам.</p></div></section></main>`;}
async function login(data){const result=await api('/login','POST',data);s.user=result.user;await reload();window.scrollTo(0,0);}

async function guestPage(token){let result;try{result=await api('/public/'+token);}catch(e){return publicError(e.message);}const e=result.event,program=result.program||[],open=e.registration_open&&e.registered<e.capacity;$('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand("/afisha")}<a class="text-button" href="/afisha">${icon('left')} Афиша</a></div><div class="guest-layout"><section class="guest-info"><div class="guest-hero">${badge('done',e.type)}<h1>${esc(e.title)}</h1></div><div class="event-meta"><span>${icon('calendar')}${dateLong(e.starts_at)} · ${esc(e.starts_at.slice(11))} (Якутск)</span><span>${icon('pin')}${esc(e.location)}</span></div><p>${esc(e.description)}</p><p class="small muted" style="margin-top:20px">${e.capacity-e.registered>0?`Осталось ${e.capacity-e.registered} мест`:'Все места заняты'}</p>${program.length?`<div class="guest-program"><h2>Программа</h2>${programList(program,{compact:true})}</div>`:''}</section><section class="guest-form"><h2>${open?'Будем рады встрече':'Регистрация закрыта'}</h2><p>${open?'Заполните форму и получите свой билет.':'Организатор больше не принимает новые заявки.'}</p>${open?`<form id="guest-form" data-token="${token}">${field('Имя и фамилия','name','','text',{placeholder:'Как к вам обращаться?',max:120})}${field('Электронная почта','email','','email',{placeholder:'name@example.com',max:200})}${field('Телефон','phone','','tel',{required:false,max:40})}${field('Организация','company','','text',{required:false,max:160})}<label class="checkbox-line"><input type="checkbox" name="consent" required><span>Согласен на обработку указанных данных организатором для регистрации и учёта участия в этом мероприятии.</span></label><p class="form-error" role="alert"></p><button class="button" type="submit">Зарегистрироваться ${icon('arrow')}</button></form><p class="small muted" style="margin-top:16px;text-align:center">Билет появится сразу после регистрации.<br>Сохраните его: отправка по почте не подключена.</p>`:'<p class="notice">Если вы уже зарегистрированы, откройте сохранённую ссылку на билет или обратитесь к организатору.</p>'}</section></div></main>`;}
async function ticketPage(token){try{const t=await api('/ticket/'+token);rememberTicket(token);$('#app').innerHTML=`<main class="guest-page"><div class="guest-top">${brand("/afisha")}<a class="text-button" href="/my-tickets">${icon('qr')} Мои билеты</a></div><article class="public-ticket"><span class="badge">Ваш входной билет</span><h1>${esc(t.title)}</h1><h3>${esc(t.name)}</h3><p>${dateLong(t.starts_at)} · ${esc(t.starts_at.slice(11))} (Якутск)</p><p>${esc(t.location)}</p><div class="ticket-qr">${qrSvg('EG:'+t.ticket)}</div>${badge(t.status)}<p class="ticket-code">EG:${t.ticket}</p><p>Покажите QR-код организатору на входе.<br>Сохраните ссылку на билет или распечатайте его.</p>${button('Сохранить или распечатать','print','printer','secondary')}${t.survey_token?`<div class="ticket-survey"><h2>Поделитесь впечатлениями</h2><p class="muted">Организатор просит оценить мероприятие. Это займёт пару минут.</p><a class="button" href="/survey/${esc(t.survey_token)}?ticket=${esc(t.ticket)}">${icon('poll')} Пройти опрос</a></div>`:''}${(t.program||[]).length?`<div class="guest-program ticket-program"><h2>Программа</h2>${programList(t.program,{compact:true})}</div>`:''}</article></main>`;}catch(e){publicError(e.message);}}
function publicError(message){$('#app').innerHTML=`<main class="guest-page">${brand()}<div class="panel section-gap">${empty('Не удалось открыть страницу',message)}</div></main>`;}
const actions={
 nav:async el=>{if(!allowedNav().some(n=>n[0]===el.dataset.view))throw new Error('Раздел доступен только организатору.');s.view=el.dataset.view;s.search='';s.filter='all';s.menu=false;location.hash=s.view;renderShell();window.scrollTo(0,0);},
 menu:()=>{s.menu=!s.menu;$('.sidebar')?.classList.toggle('open',s.menu);$('.mobile-overlay')?.classList.toggle('open',s.menu);},
 'open-event':async el=>{s.eventId=Number(el.dataset.id);s.view='overview';s.search='';s.filter='all';location.hash='overview';await reload();window.scrollTo(0,0);},
 'new-event':()=>eventForm(), 'edit-event':()=>eventForm(s.eventId),
 'delete-event':el=>confirmDelete('events',el.dataset.id,'мероприятие'),
 'new-task':()=>taskForm(), 'edit-task':el=>taskForm(el.dataset.id), task:el=>taskDetail(el.dataset.id),
 'delete-task':el=>confirmDelete('tasks',el.dataset.id,'задачу'),
 notifications:()=>notificationsModal(), 'open-notification':el=>openNotification(Number(el.dataset.index)),
 'new-guest':()=>guestForm(), 'import-guests':()=>importGuestsForm(),
 'new-program':()=>programForm(), 'edit-program':el=>programForm(el.dataset.id),
 'delete-program':el=>confirmDelete('program',el.dataset.id,'пункт программы'),
 'new-survey':()=>surveyForm(),'edit-survey':()=>surveyForm(),
 'survey-status':async el=>{if(!s.survey?.survey)return;const status=el.dataset.status;await api(`/events/${s.eventId}/survey`,'PUT',{title:s.survey.survey.title,description:s.survey.survey.description,status,questions:s.survey.questions.map(q=>({id:q.id,text:q.text,kind:q.kind,options:q.options,required:q.required}))});await loadSurvey();toast(status==='open'?'Приём ответов открыт':'Опрос закрыт');},
 'copy-survey':async()=>{const url=location.origin+'/survey/'+s.survey.survey.public_token;try{await navigator.clipboard.writeText(url);toast('Ссылка скопирована');}catch{toast('Скопируйте ссылку вручную',true);}},
 'delete-survey':()=>{openModal('Удалить опрос','<p>Все ответы гостей тоже будут удалены. Это действие нельзя отменить.</p>',{submit:'Удалить',onSubmit:async()=>{await api(`/events/${s.eventId}/survey`,'DELETE');s.survey={eventId:s.eventId,survey:null};await reload();toast('Опрос удалён');}});},
 'survey-add-q':()=>{const list=readSurveyQuestions();list.push({text:'',kind:'text',options:[],required:false});renderSurveyQuestions(list);},
 'survey-remove-q':el=>{const list=readSurveyQuestions();list.splice(Number(el.dataset.index),1);if(!list.length)list.push({text:'',kind:'rating',options:[],required:true});renderSurveyQuestions(list);},
 'toggle-task':async el=>{const t=s.data.tasks.find(t=>t.id===Number(el.dataset.id));await saved('/tasks/'+t.id,'PATCH',{status:t.status==='done'?'progress':'done'},t.status==='done'?'Задача возвращена в работу':'Задача выполнена');},
 filter:el=>{s.filter=el.dataset.filter;renderMain();}, board:()=>{s.board=!s.board;renderMain();},
 'new-expense':()=>expenseForm(), 'edit-expense':el=>expenseForm(el.dataset.id), 'delete-expense':el=>confirmDelete('expenses',el.dataset.id,'статью расходов'),
 'new-person':()=>personForm(), 'edit-person':el=>personForm(el.dataset.id), 'delete-person':el=>confirmDelete('team',el.dataset.id,'участника'),
 registration, 'copy-registration':async()=>{const url=location.origin+'/register/'+s.data.event.public_token;try{await navigator.clipboard.writeText(url);toast('Ссылка скопирована');}catch{const input=$('#modal input');input.select();toast('Выделили ссылку. Нажмите Ctrl+C.');}},
 'toggle-registration':async()=>{await api('/events/'+s.eventId,'PATCH',{registration_open:!s.data.event.registration_open});await reload(false);registration();renderMain();toast('Настройки регистрации сохранены');},
 ticket:el=>ticketModal(el.dataset.ticket), checkin, camera:scanCamera, upload:el=>upload(el.dataset.task), 'delete-file':el=>confirmDelete('files',el.dataset.id,'файл'),
 month:el=>{const [y,m]=s.month.split('-').map(Number),d=new Date(y,m-1+Number(el.dataset.delta),1);s.month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');renderMain();},
 'month-today':()=>{s.month=today().slice(0,7);renderMain();},
 profile,password:passwordForm,logout:async()=>{await api('/logout','POST');s.user=null;closeModal();renderLogin();},
 'demo-organizer':()=>login({email:'organizer@eventgo.local',password:'EventGo2026!'}),'demo-member':()=>login({email:'team@eventgo.local',password:'TeamGo2026!'}),
 close:closeModal, print:()=>window.print()
};
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const fn=actions[el.dataset.action];if(!fn)return;event.preventDefault();el.disabled=true;try{await fn(el);}catch(error){toast(error.message,true);}finally{el.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.matches('[data-search]')){s.search=event.target.value;renderMain();}});
document.addEventListener('change',async event=>{const el=event.target,kind=el.dataset.change;if(!kind)return;el.disabled=true;try{if(kind==='event'){s.eventId=Number(el.value);s.filter='all';s.search='';await reload();}else if(kind==='task-status')await saved('/tasks/'+el.dataset.id,'PATCH',{status:el.value});else if(kind==='guest-status'){if(el.dataset.attended&&!confirm('Снять отметку входа у этого гостя? Билет снова станет действительным.')){await reload();return;}await saved('/guests/'+el.dataset.id,'PATCH',{status:el.value});}}catch(error){toast(error.message,true);await reload();}finally{el.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['login-form','modal-form','guest-form'].includes(form.id))return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;form.querySelector('.form-error').textContent='';try{if(form.id==='login-form')await login(formObject(form));else if(form.id==='modal-form'){const callback=modalSubmit;if(callback){const result=await callback(form);if(result!==false)closeModal();}}else{const p=formObject(form);p.consent=form.consent.checked;const result=await api('/public/'+form.dataset.token,'POST',p);rememberTicket(result.ticket);location.href='/ticket/'+result.ticket;}}catch(error){form.querySelector('.form-error').textContent=error.message;}finally{submit.disabled=false;}});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(s.user&&allowedNav().some(n=>n[0]===view)&&view!==s.view){s.view=view;s.filter='all';s.search='';renderShell();}});
async function boot(){if(location.pathname==='/afisha'){await afishaPage();return;}if(location.pathname==='/my-tickets'){await walletPage();return;}const match=location.pathname.match(/^\/(register|ticket|survey)\/([a-f0-9]{32})$/);if(match){if(match[1]==='register')await guestPage(match[2]);else if(match[1]==='survey')await surveyPage(match[2]);else await ticketPage(match[2]);return;}try{const result=await api('/me');s.user=result.user;if(s.user)await reload();else renderLogin();}catch(error){publicError('Не удалось связаться с сервером. Убедитесь, что окно запуска EventGo открыто.');}}

function ticketCodes(){try{const items=JSON.parse(localStorage.getItem('eventgo-tickets')||'[]');return Array.isArray(items)?[...new Set(items.filter(x=>typeof x==='string'&&/^[a-f0-9]{32}$/.test(x)))].slice(0,100):[];}catch{return [];}}
function rememberTicket(token){try{localStorage.setItem('eventgo-tickets',JSON.stringify([token,...ticketCodes().filter(x=>x!==token)].slice(0,100)));}catch{}}
function guestHeader(active){return `<div class="guest-top public-top">${brand("/afisha")}<nav aria-label="Навигация гостя"><a class="${active==='afisha'?'selected':''}" href="/afisha">Афиша</a><a class="${active==='tickets'?'selected':''}" href="/my-tickets">${icon('qr')} Мои билеты</a></nav><span class="badge">Гость</span></div>`;}
let posterEvents=[],posterFilter='all';
async function afishaPage(){try{posterEvents=await api('/afisha');$('#app').innerHTML=`<main class="poster-page">${guestHeader('afisha')}<section class="poster-hero"><div><span class="poster-eyebrow">EVENTGO · АФИША</span><h1>Встречаемся<br>на событиях.</h1><p>Находите интересные мероприятия, регистрируйтесь<br>и сохраняйте электронный билет.</p><a class="button light" href="/my-tickets">${icon('qr')} Открыть мои билеты ${icon('arrow')}</a></div><div class="poster-art" aria-hidden="true"><div class="poster-orbit"></div><div class="poster-mini">${icon('spark')}<strong>Новые идеи.<br>Новые знакомства.</strong><span>Ваше следующее событие — здесь</span></div></div></section><div class="page-heading"><div><h2>Выбирайте своё событие</h2><p class="description">Текущие и предстоящие мероприятия</p></div></div><div class="toolbar"><div class="tabs" id="poster-tabs">${[['all','Все события'],['active','Проходят сейчас'],['planning','Скоро']].map(([key,label])=>`<button class="tab ${key===posterFilter?'active':''}" data-poster-filter="${key}">${label}</button>`).join('')}</div><label class="search">${icon('search')}<input data-poster-search placeholder="Название или место" aria-label="Поиск по афише"></label></div><div id="poster-events"></div><footer class="guest-footer">Гостевой режим · <a href="/">Вход для организатора и команды</a></footer></main>`;renderPosterCards();}catch(error){publicError(error.message);}}
function renderPosterCards(){const search=($('[data-poster-search]')?.value||'').toLowerCase();const events=posterEvents.filter(e=>(posterFilter==='all'||e.status===posterFilter)&&[e.title,e.location,e.type].join(' ').toLowerCase().includes(search));$('#poster-events').innerHTML=events.length?`<div class="event-cards">${events.map((e,i)=>`<article class="event-card"><div class="event-art ${['','orange','lime'][i%3]}">${icon(e.type==='Хакатон'?'spark':e.type==='Встреча'?'team':'calendar')}${badge(e.status)}</div><div class="event-card-body"><span class="small muted">${esc(e.type)}</span><h2>${esc(e.title)}</h2><p>${icon('calendar')}${dateLong(e.starts_at)} · ${esc(e.starts_at.slice(11))} (Якутск)</p><p>${icon('pin')}${esc(e.location)}</p><p class="poster-description">${esc(e.description)}</p><div class="event-card-bottom"><span>${e.registration_open&&e.registered<e.capacity?'Осталось мест: '+(e.capacity-e.registered):'Регистрация закрыта'}</span><a class="text-button" href="/register/${e.public_token}">${e.registration_open&&e.registered<e.capacity?'Зарегистрироваться':'О событии'} ${icon('arrow')}</a></div></div></article>`).join('')}</div>`:`<div class="panel">${empty('События не найдены','Попробуйте другой запрос или вернитесь к афише позже.')}</div>`;}
async function walletPage(){
 $('#app').innerHTML=`<main class="poster-page">${guestHeader('tickets')}<div class="page-heading"><div><p class="eyebrow">Всё готово к встрече</p><h1>Мои билеты</h1><p class="description">Откройте билет и покажите QR-код на экране при входе.</p></div><a class="button secondary" href="/afisha">${icon('calendar')} К афише</a></div><div id="wallet-tickets"><p class="muted">Загружаем билеты…</p></div><section class="panel pad section-gap"><h2>Уже есть билет?</h2><p class="small muted" style="margin:8px 0 16px">Вставьте код EG:… или ссылку на электронный билет с другого устройства.</p><form id="ticket-import-form" class="ticket-import">${field('Код билета или ссылка','ticket','','text',{placeholder:'EG:…',max:300})}<button class="button" type="submit">${icon('plus')} Добавить билет</button><p class="form-error" role="alert"></p></form></section><p class="small muted" style="margin-top:20px">Билеты сохраняются в этом браузере. Для переноса на другой телефон сохраните ссылку или код билета.</p></main>`;
 const results=await Promise.all(ticketCodes().map(async code=>{try{return await api('/ticket/'+code);}catch{return null;}}));
 const tickets=results.filter(Boolean);$('#wallet-tickets').innerHTML=tickets.length?`<div class="ticket-wallet">${tickets.map(t=>`<article class="wallet-card"><div class="wallet-card-top">${icon('qr')}${badge(t.status)}</div><h2>${esc(t.title)}</h2><p class="muted">${esc(t.name)}</p><p class="small muted">${dateLong(t.starts_at)} · ${esc(t.starts_at.slice(11))}</p><p class="small muted">${esc(t.location)}</p><a class="button" href="/ticket/${t.ticket}">${icon('qr')} Показать билет ${icon('arrow')}</a></article>`).join('')}</div>`:`<div class="panel">${empty('Ваш первый билет ещё впереди','Зарегистрируйтесь на событие из афиши — билет появится здесь.','<a class="button" href="/afisha">Выбрать событие</a>')}</div>`;
}
document.addEventListener('input',event=>{if(event.target.matches('[data-poster-search]'))renderPosterCards();});
document.addEventListener('click',event=>{const el=event.target.closest('[data-poster-filter]');if(!el)return;posterFilter=el.dataset.posterFilter;$('#poster-tabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===el));renderPosterCards();});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='ticket-import-form')return;event.preventDefault();const button=form.querySelector('button');button.disabled=true;form.querySelector('.form-error').textContent='';try{const value=formObject(form).ticket.trim();const code=/^EG:([a-f0-9]{32})$/i.exec(value)?.[1]||/\/ticket\/([a-f0-9]{32})(?:[?#].*)?$/i.exec(value)?.[1]||(/^[a-f0-9]{32}$/i.test(value)?value:null);if(!code)throw new Error('Укажите полный код или ссылку на билет.');await api('/ticket/'+code.toLowerCase());rememberTicket(code.toLowerCase());await walletPage();toast('Билет добавлен');}catch(error){form.querySelector('.form-error').textContent=error.message;}finally{button.disabled=false;}});

await boot();
setInterval(async()=>{if(!s.user||['chat','assistant'].includes(s.view)||$('#modal').open||document.hidden||document.activeElement?.matches('input,textarea,select')||loading)return;loading=true;try{await reload();}catch{}finally{loading=false;}},20000);
